import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();

        if (s.startsWith("dot") || s.startsWith("at") || s.endsWith("at") || s.endsWith("dot")) {
            if (s.startsWith("dot")) {
                String t = s.substring(3);
                String[] parts = t.split("dot");
                String joined = String.join(".", parts);
                int index_at = joined.indexOf("at");
                String replaced = joined.substring(0, index_at) + "@" + joined.substring(index_at + 2);
                String q = "dot" + replaced;
                if (q.endsWith(".")) {
                    s = q.substring(0, q.length() - 1) + "dot";
                } else if (q.endsWith("@")) {
                    s = q.substring(0, q.length() - 1) + "at";
                } else {
                    s = q;
                }
            }

            if (s.startsWith("at")) {
                String t = s.substring(2);
                String[] parts = t.split("dot");
                String joined = String.join(".", parts);
                int index_at = joined.indexOf("at");
                String replaced = joined.substring(0, index_at) + "@" + joined.substring(index_at + 2);
                String q = "at" + replaced;
                if (q.endsWith(".")) {
                    s = q.substring(0, q.length() - 1) + "dot";
                } else if (q.endsWith("@")) {
                    s = q.substring(0, q.length() - 1) + "at";
                } else {
                    s = q;
                }
            }

            if (s.endsWith("dot") && !s.startsWith("dot") && !s.startsWith("at")) {
                String t = s.substring(0, s.length() - 3);
                String[] parts = t.split("dot");
                String joined = String.join(".", parts);
                int index_at = joined.indexOf("at");
                String replaced = joined.substring(0, index_at) + "@" + joined.substring(index_at + 2);
                s = replaced + "dot";
            }

            if (s.endsWith("at") && !s.startsWith("dot") && !s.startsWith("at")) {
                String t = s.substring(0, s.length() - 2);
                String[] parts = t.split("dot");
                String joined = String.join(".", parts);
                int index_at = joined.indexOf("at");
                String replaced = joined.substring(0, index_at) + "@" + joined.substring(index_at + 2);
                s = replaced + "at";
            }

            System.out.println(s);
        } else {
            String[] parts = s.split("dot");
            String joined = String.join(".", parts);
            int index_at = joined.indexOf("at");
            String result = joined.substring(0, index_at) + "@" + joined.substring(index_at + 2);
            System.out.println(result);
        }
        scanner.close();
    }
}
